    {
      "name": "Alice's reservation price",
      "hypothesis": "Higher reservation price leads to higher final price",
      "predicted_direction": "increase",
      "treatment_values": ["$15", "$20", "$25"]
    },
    {
      "name": "Bob's maximum willingness to pay",
      "hypothesis": "Higher maximum willingness to pay leads to higher final price",
      "predicted_direction": "increase",
      "treatment_values": ["$15", "$20", "$25"]
    },
    {
      "name": "Mug's true value",
      "hypothesis": "Higher true value leads to higher final price",
      "predicted_direction": "increase",
      "treatment_values": ["$10", "$15", "$20"]
    }
  ],
  "information_scope": {
    "public": ["mug's description"],
    "private": [
      {
        "agent": "Alice",
        "information": ["mug's true value", "Alice's reservation price"]
      },
      {
        "agent": "Bob",
        "information": ["Bob's maximum willingness to pay"]
      }
    ]
  },
  "interaction": {
    "order": ["Alice", "Bob"],
    "max_turns": 2,
    "stopping_rule": "agreement on a price or refusal to trade"
  }
}

