      "predicted_direction": "increase",
      "treatment_values": ["Basic legal knowledge", "Advanced legal knowledge", "No legal knowledge"]
    },
    {
      "name": "Communication skills",
      "hypothesis": "Strong communication skills improve the likelihood of hiring",
      "predicted_direction": "increase",
