{
  "schema_version": "scientist-design-v1",
  "scenario": "3 bidders participating in an auction for a piece of art starting at fifty dollars",
  "agents": [
    {
      "name": "Agent A",
      "role": "Conservative bidder",
      "goal": "Maximize profit while minimizing risk",
      "constraints": ["Bids only when confident about the art's value"]
    },
    {
      "name": "Agent B",
      "role": "Speculative bidder",
      "goal": "Achieve maximum gain regardless of risk",
      "constraints": ["Bids incrementally based on others' actions"]
    },
    {
      "name": "Agent C",
      "role": "Strategic bidder",
      "goal": "Outbid others without overpaying",
      "constraints": ["Bids based on perceived value and competition"]
    }
  ],
  "outcome": {
    "name": "Final auction price",
    "operationalization": "The highest bid accepted by the auctioneer",
    "measurement_question": "What is the final price the art sells for?",
    "respondent": "Auctioneer"
  },
  "causes": [
    {
      "name": "Bidder's confidence in art value",
      "hypothesis": "Higher confidence leads to higher bids",
      "predicted_direction": "increase",
      "treatment_values": ["High", "Medium", "Low"]
    },
    {
      "name": "Previous auction experience",
      "hypothesis": "More experience leads to more strategic bidding",
      "predicted_direction": "increase",
      "treatment_values": ["Novice", "Intermediate", "Expert"]
    },
    {
      "name": "Market demand signal",
      "hypothesis": "Higher demand signals lead to increased competition",
      "predicted_direction": "increase",
      "treatment_values": ["High demand", "Moderate demand", "Low demand"]
    }
  ],
  "information_scope": {
    "public": ["Starting bid", "Current highest bid"],
    "private": [
      {
        "agent": "Agent A",
        "information": ["Personal valuation of art", "Risk tolerance level"]
      },
      {
        "agent": "Agent B",
        "information": ["Estimated market value", "Bid history"]
      },
      {
        "agent": "Agent C",
        "information": ["Competitor's bid history", "Art's provenance"]
      }
    ]
  },
  "interaction": {
    "order": ["Agent A", "Agent B", "Agent C"],
    "max_turns": 3,
    "stopping_rule": "Auction ends when no further bids are placed"
  }
}

